import org.junit.platform.launcher.core.*;import org.junit.platform.launcher.listeners.*;import static org.junit.platform.engine.discovery.DiscoverySelectors.*;public class ReviewLauncher{public static void main(String[]args){var l=new SummaryGeneratingListener();var b=LauncherDiscoveryRequestBuilder.request();for(String s:args)b.selectors(selectClass("com.cryptoautotrader.api.service."+s));var x=LauncherFactory.create();x.registerTestExecutionListeners(l);x.execute(b.build());l.getSummary().printTo(new java.io.PrintWriter(System.out,true));l.getSummary().printFailuresTo(new java.io.PrintWriter(System.out,true));System.exit(l.getSummary().getTestsFailedCount()+l.getSummary().getContainersFailedCount()>0?1:0);}}